void Record(DiagnosticEvent e)
{
    eventStore.Append(e); // 不以新狀態覆蓋舊事件
    if (e.Outcome == "Unknown")
        metrics.CountUnclassified(e.Stage);
}

public sealed record DiagnosticEvent(
    string WorkId, string Endpoint, string Direction,
    string ProfileRevision, string Stage, string Outcome,
    DateTimeOffset ObservedAt, string TimeSource,
    string? RawDeviceCode, string? EvidenceRef);
